import { applyIconifyConfig, setIconifyConfig } from "./iconify-config.js";
import { getSideProvider } from "./provider.js";
import { defineNuxtPlugin, onNuxtReady, useAppConfig, useRequestFetch, useRuntimeConfig } from "#imports";
export default defineNuxtPlugin({
  name: "@nuxt/icon",
  async setup(nuxtApp) {
    const configs = useRuntimeConfig();
    const options = useAppConfig().icon;
    const requestFetch = useRequestFetch();
    const nativeFetch = requestFetch.native;
    const provider = getSideProvider(options.provider, import.meta.server ? "server" : "client");
    const resources = [];
    if (provider === "server") {
      const baseURL = configs.app?.baseURL?.replace(/\/$/, "") ?? "";
      resources.push(baseURL + (options.localApiEndpoint || "/api/_nuxt_icon"));
      if (options.fallbackToApi === true || options.fallbackToApi === "client-only") {
        resources.push(options.iconifyApiEndpoint);
      }
    } else if (provider !== "none") {
      resources.push(options.iconifyApiEndpoint);
    }
    async function loadCustomIconsChunk(icons, prefix) {
      try {
        const data = await requestFetch(resources[0] + "/" + prefix + ".json", {
          query: {
            icons: icons.join(",")
          }
        });
        if (!data || data.prefix !== prefix || !data.icons)
          throw new Error("Invalid data" + JSON.stringify(data));
        return data;
      } catch (e) {
        console.error("Failed to load custom icons", e);
        return null;
      }
    }
    async function customIconLoader(icons, prefix) {
      const chunks = [[]];
      let length = 0;
      for (const name of icons) {
        const nameLength = encodeURIComponent(name).length;
        if (length + nameLength > 2e3 && chunks.at(-1).length) {
          chunks.push([]);
          length = 0;
        }
        chunks.at(-1).push(name);
        length += nameLength + 1;
      }
      const results = (await Promise.all(chunks.map((chunk) => loadCustomIconsChunk(chunk, prefix)))).filter((data) => !!data);
      if (!results.length)
        return null;
      return results.reduce((acc, data) => ({
        ...acc,
        ...data,
        icons: { ...acc.icons, ...data.icons },
        aliases: { ...acc.aliases, ...data.aliases }
      }));
    }
    setIconifyConfig({
      resources,
      fetch: provider === "none" ? () => Promise.resolve(new Response()) : (input, init) => {
        const nitroFetch = globalThis.$fetch?.native;
        return (nativeFetch || nitroFetch || globalThis.fetch)(input, init);
      },
      customIconsLoader: customIconLoader,
      customCollections: options.customCollections || []
    });
    if (import.meta.server) {
      applyIconifyConfig(await import("@iconify/vue"));
      return;
    }
    if (options.mode !== "svg") {
      const preload = () => import("./components/css-runtime.js").then((r) => r.setupIconify()).catch(() => {
      });
      if (nuxtApp.isHydrating)
        onNuxtReady(preload);
      else
        preload();
    }
  }
  // For type portability
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
});
